/**
 * The annotation for one command.
 */
public struct CommandSpec: Equatable, Hashable {
    public var kind: CommandKind
    /**
     * Stable dotted identifier, e.g. `battery.get`.
     */
    public var id: String
    public var title: String
    public var category: Category
    /**
     * What the command does and when to use it.
     */
    public var summary: String
    public var format: FrameFormat
    public var command: UInt8
    /**
     * `None` for 6E frames, which have no action byte.
     */
    public var action: Action?
    public var writeChannel: WriteChannel
    public var expectsResponse: Bool
    /**
     * Reply code that completes the request. The generic ack
     * `01 81 [code, status]` for this code completes it too.
     */
    public var responseCommand: UInt8?
    /**
     * Other reply codes that also complete it (e.g. stock firmware's empty
     * `0x2A` echo where patched firmware answers `0xDC`).
     */
    public var alternateResponseCommands: Data
    public var multiResponse: Bool
    /**
     * Base timeout; record syncs scale it with the expected count.
     */
    public var timeoutMs: UInt32
    /**
     * Payload layout, bytes in order.
     */
    public var requestLayout: String
    public var responseLayout: String
    public var evidence: Evidence
    public var firmware: FirmwareSupport
    public var notes: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(kind: CommandKind, 
        /**
         * Stable dotted identifier, e.g. `battery.get`.
         */id: String, title: String, category: Category, 
        /**
         * What the command does and when to use it.
         */summary: String, format: FrameFormat, command: UInt8, 
        /**
         * `None` for 6E frames, which have no action byte.
         */action: Action?, writeChannel: WriteChannel, expectsResponse: Bool, 
        /**
         * Reply code that completes the request. The generic ack
         * `01 81 [code, status]` for this code completes it too.
         */responseCommand: UInt8?, 
        /**
         * Other reply codes that also complete it (e.g. stock firmware's empty
         * `0x2A` echo where patched firmware answers `0xDC`).
         */alternateResponseCommands: Data, multiResponse: Bool, 
        /**
         * Base timeout; record syncs scale it with the expected count.
         */timeoutMs: UInt32, 
        /**
         * Payload layout, bytes in order.
         */requestLayout: String, responseLayout: String, evidence: Evidence, firmware: FirmwareSupport, notes: String) {
        self.kind = kind
        self.id = id
        self.title = title
        self.category = category
        self.summary = summary
        self.format = format
        self.command = command
        self.action = action
        self.writeChannel = writeChannel
        self.expectsResponse = expectsResponse
        self.responseCommand = responseCommand
        self.alternateResponseCommands = alternateResponseCommands
        self.multiResponse = multiResponse
        self.timeoutMs = timeoutMs
        self.requestLayout = requestLayout
        self.responseLayout = responseLayout
        self.evidence = evidence
        self.firmware = firmware
        self.notes = notes
    }

    

    
}

