        self.commandNotify = commandNotify
        self.remoteWrite = remoteWrite
        self.remoteNotify = remoteNotify
        self.transparentNotify = transparentNotify
        self.otaControl = otaControl
        self.otaData = otaData
        self.heartRateMeasurement = heartRateMeasurement
        self.deviceNamePrefixes = deviceNamePrefixes
    }

    

    
}

