/**
 * The 6F action byte.
 */

public enum Action: Equatable, Hashable {
    
    /**
     * `0x70`: read/query.
     */
    case check
    /**
     * `0x71`: write/configure.
     */
    case set
    /**
     * `0x80`: reply to a check (also used by a few phone→watch pushes).
     */
    case checkResponse
    /**
     * `0x81`: reply to a set; the generic ack `01 81 [cmd, status]` uses it.
     */
    case setResponse
    /**
     * Any other byte, kept verbatim.
     */
    case other(raw: UInt8
    )





}

#if compiler(>=6)
extension Action: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
