    typealias SwiftType = Action

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Action {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .check
        
        case 2: return .set
        
        case 3: return .checkResponse
        
        case 4: return .setResponse
        
        case 5: return .other(raw: try FfiConverterUInt8.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Action, into buf: inout [UInt8]) {
        switch value {
        
        
        case .check:
            writeInt(&buf, Int32(1))
        
        
        case .set:
            writeInt(&buf, Int32(2))
        
        
        case .checkResponse:
            writeInt(&buf, Int32(3))
        
        
        case .setResponse:
            writeInt(&buf, Int32(4))
        
        
        case let .other(raw):
            writeInt(&buf, Int32(5))
            FfiConverterUInt8.write(raw, into: &buf)
            
        }
    }
}


