        case 2: return .noStockHandler
        
        case 3: return .ignored6e
        
        case 4: return .patched(feature: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FirmwareSupport, into buf: inout [UInt8]) {
