/**
 * A completed reply.
 */

public enum Response: Equatable, Hashable {
    
    /**
     * The generic ack. Status 0 = applied; 1 = rejected or no data;
     * 2 = no handler for the command.
     */
    case ack(command: UInt8, status: UInt8
    )
    case bindStart(userId: UInt32
    )
    case bindEnd(firstBind: Bool
    )
    case watchId(id: String
    )
    case version(text: String, parsed: FirmwareVersion?
    )
    case battery(status: BatteryStatus
    )
    case brightness(level: UInt8, percent: UInt8
    )
    case screenTimeout(seconds: UInt8
    )
    case vibration(settings: VibrationSettings
    )
    case vibrationStrength(value: UInt8
    )
    case switches(states: SwitchStates, raw: Data
    )
    case unit(metric: Bool
    )
    case unitsAndFormat(value: UnitsAndFormat
    )
    case goals(goals: Goals
    )
    case goal6e(kind: Goal6eKind, value: UInt32
    )
    case sleepWindow(window: SleepWindow
    )
    case inactivityAlert(alert: InactivityAlert
    )
    case autoHeartRate(value: AutoHeartRate
    )
    case dataCounts(counts: DataCounts
    )
    case sportRecords(records: [SportRecord]
    )
    case sleepPoints(points: [SleepPoint]
    )
    case heartRateSamples(samples: [HeartRateSample]
    )
    case workoutCount(count: UInt16
    )
    case workouts(records: [WorkoutRecord]
    )
    case workoutHeartRateCount(count: UInt32
    )
    case workoutHeartRate(samples: [WorkoutHeartRateSample]
    )
    case count6e(count: UInt32
    )
    case sportRecord6e(timestamp: Int64, steps: UInt32, calories: UInt32
    )
    case sleepPoint6e(timestamp: Int64, status: UInt8
    )
    case alarmCounts(counts: AlarmCounts
    )
    case alarms(alarms: [Alarm]
    )
    case freeAlarmId(id: UInt8
    )
    case reminder(reminder: Reminder
    )
    /**
     * The watch finished sending 6E reminders (each arrives as an event).
     */
    case remindersSent
    case watchFaces(faces: [WatchFace]
    )
    case pageOrder(pages: Data, reportedCount: UInt8?, raw: Data
    )
    case pageRouteTrace(trace: PageRouteTrace
    )
    case capabilities(value: Capabilities
    )
    /**
     * Raw bytes from a memory or resource read; empty when rejected.
     */
    case bytes(data: Data
    )
    /**
     * The reply to a `Raw` request.
     */
    case packet(packet: Packet
    )
    /**
     * A matching reply that was too short or malformed to decode.
     */
    case unparsed(packet: Packet
    )





}

