public enum SessionEvent: Equatable, Hashable {
    
    /**
     * Every decoded frame, with the request that consumed it, if any.
     */
    case received(packet: Packet, message: WatchMessage, consumedBy: UInt64?
    )
    /**
     * One more record of a sync; `latest` is just that record.
     */
    case progress(requestId: UInt64, received: UInt32, total: UInt32, latest: Response?
    )
    case completed(requestId: UInt64, response: Response
    )
    /**
     * No reply in time. `partial` holds collected records or the
     * documented empty result for probes.
     */
    case timedOut(requestId: UInt64, partial: Response?
    )
    case cancelled(requestId: UInt64
    )





}

#if compiler(>=6)
extension SessionEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSessionEvent: FfiConverterRustBuffer {
    typealias SwiftType = SessionEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SessionEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .received(packet: try FfiConverterTypePacket.read(from: &buf), message: try FfiConverterTypeWatchMessage.read(from: &buf), consumedBy: try FfiConverterOptionUInt64.read(from: &buf)
        )
        
        case 2: return .progress(requestId: try FfiConverterUInt64.read(from: &buf), received: try FfiConverterUInt32.read(from: &buf), total: try FfiConverterUInt32.read(from: &buf), latest: try FfiConverterOptionTypeResponse.read(from: &buf)
        )
        
        case 3: return .completed(requestId: try FfiConverterUInt64.read(from: &buf), response: try FfiConverterTypeResponse.read(from: &buf)
        )
        
        case 4: return .timedOut(requestId: try FfiConverterUInt64.read(from: &buf), partial: try FfiConverterOptionTypeResponse.read(from: &buf)
        )
        
        case 5: return .cancelled(requestId: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SessionEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .received(packet,message,consumedBy):
            writeInt(&buf, Int32(1))
            FfiConverterTypePacket.write(packet, into: &buf)
            FfiConverterTypeWatchMessage.write(message, into: &buf)
            FfiConverterOptionUInt64.write(consumedBy, into: &buf)
            
        
        case let .progress(requestId,received,total,latest):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(requestId, into: &buf)
            FfiConverterUInt32.write(received, into: &buf)
            FfiConverterUInt32.write(total, into: &buf)
            FfiConverterOptionTypeResponse.write(latest, into: &buf)
            
        
        case let .completed(requestId,response):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(requestId, into: &buf)
            FfiConverterTypeResponse.write(response, into: &buf)
            
        
        case let .timedOut(requestId,partial):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(requestId, into: &buf)
            FfiConverterOptionTypeResponse.write(partial, into: &buf)
            
        
        case let .cancelled(requestId):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(requestId, into: &buf)
            
        }
    }
}


