/**
 * What a received frame means.
 */

public enum WatchMessage: Equatable, Hashable {
    
    /**
     * Generic ack `01 81 [command, status]`.
     */
    case ack(command: UInt8, status: UInt8
    )
    /**
     * Battery reply (`0x08`), new-mode encoding.
     */
    case battery(status: BatteryStatus
    )
    /**
     * Patched battery stream (`E4 71 [level, state]`); state 2 = on charger.
     */
    case batteryStream(level: UInt8, onCharger: Bool
    )
    /**
     * Find phone (`D2 71 [00 start | 01 stop]`). Reply to a start with
     * `FindPhoneStartAck` on the remote channel.
     */
    case findPhone(ringing: Bool
    )
    case musicControl(action: MusicControl
    )
    case deviceControl(action: DeviceControl
    )
    case phoneGps(event: PhoneGpsEvent
    )
    /**
     * Patched live workout heart rate (`E2 71 [bpm (cal_milli_le32)]`).
     */
    case liveHeartRate(bpm: UInt8, caloriesKcal: UInt32?
    )
    /**
     * Real-time heart rate (`0x5D`).
     */
    case realTimeHeartRate(bpm: UInt8
    )
    /**
     * A reminder sent by the watch after `GetReminders6e` (6E `0x11`).
     */
    case reminder6e(kind: ReminderKind, hour: UInt8, minute: UInt8, weekdays: UInt8
    )
    /**
     * Anything else, usually a reply to a request.
     */
    case reply(command: UInt8
    )





}

