        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .ack(command: try FfiConverterUInt8.read(from: &buf), status: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 2: return .battery(status: try FfiConverterTypeBatteryStatus.read(from: &buf)
        )
        
        case 3: return .batteryStream(level: try FfiConverterUInt8.read(from: &buf), onCharger: try FfiConverterBool.read(from: &buf)
        )
        
        case 4: return .findPhone(ringing: try FfiConverterBool.read(from: &buf)
        )
        
        case 5: return .musicControl(action: try FfiConverterTypeMusicControl.read(from: &buf)
        )
        
        case 6: return .deviceControl(action: try FfiConverterTypeDeviceControl.read(from: &buf)
        )
        
        case 7: return .phoneGps(event: try FfiConverterTypePhoneGpsEvent.read(from: &buf)
        )
        
        case 8: return .liveHeartRate(bpm: try FfiConverterUInt8.read(from: &buf), caloriesKcal: try FfiConverterOptionUInt32.read(from: &buf)
        )
        
        case 9: return .realTimeHeartRate(bpm: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 10: return .reminder6e(kind: try FfiConverterTypeReminderKind.read(from: &buf), hour: try FfiConverterUInt8.read(from: &buf), minute: try FfiConverterUInt8.read(from: &buf), weekdays: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 11: return .reply(command: try FfiConverterUInt8.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WatchMessage, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .ack(command,status):
            writeInt(&buf, Int32(1))
            FfiConverterUInt8.write(command, into: &buf)
            FfiConverterUInt8.write(status, into: &buf)
            
        
        case let .battery(status):
            writeInt(&buf, Int32(2))
            FfiConverterTypeBatteryStatus.write(status, into: &buf)
            
        
        case let .batteryStream(level,onCharger):
            writeInt(&buf, Int32(3))
            FfiConverterUInt8.write(level, into: &buf)
            FfiConverterBool.write(onCharger, into: &buf)
            
        
        case let .findPhone(ringing):
            writeInt(&buf, Int32(4))
            FfiConverterBool.write(ringing, into: &buf)
            
        
        case let .musicControl(action):
            writeInt(&buf, Int32(5))
            FfiConverterTypeMusicControl.write(action, into: &buf)
            
        
        case let .deviceControl(action):
            writeInt(&buf, Int32(6))
            FfiConverterTypeDeviceControl.write(action, into: &buf)
            
        
        case let .phoneGps(event):
            writeInt(&buf, Int32(7))
            FfiConverterTypePhoneGpsEvent.write(event, into: &buf)
            
        
        case let .liveHeartRate(bpm,caloriesKcal):
            writeInt(&buf, Int32(8))
            FfiConverterUInt8.write(bpm, into: &buf)
            FfiConverterOptionUInt32.write(caloriesKcal, into: &buf)
            
        
        case let .realTimeHeartRate(bpm):
            writeInt(&buf, Int32(9))
            FfiConverterUInt8.write(bpm, into: &buf)
            
        
        case let .reminder6e(kind,hour,minute,weekdays):
            writeInt(&buf, Int32(10))
            FfiConverterTypeReminderKind.write(kind, into: &buf)
            FfiConverterUInt8.write(hour, into: &buf)
            FfiConverterUInt8.write(minute, into: &buf)
            FfiConverterUInt8.write(weekdays, into: &buf)
            
        
        case let .reply(command):
            writeInt(&buf, Int32(11))
            FfiConverterUInt8.write(command, into: &buf)
            
        }
    }
