fileprivate struct FfiConverterSequenceTypeSessionEvent: FfiConverterRustBuffer {
    typealias SwiftType = [SessionEvent]

    public static func write(_ value: [SessionEvent], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeSessionEvent.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [SessionEvent] {
        let len: Int32 = try readInt(&buf)
        var seq = [SessionEvent]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeSessionEvent.read(from: &buf))
        }
        return seq
    }
}
